import { buildPlan } from './build-models.js?v=92ee1f3623';
import { createComparisonViews } from './comparison-views.js?v=7543cb51df';
import { RESEARCH as R } from './data/research.js?v=cf3edb5e15';
import { scorePlatforms, unitEconomics, portfolioCosts, allocation, DEFAULT_WEIGHTS } from './models.js?v=576e792f61';

export const esc = (value = '') => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const icon = name => `<svg class="icon" aria-hidden="true"><use href="assets/icons.svg#${name}"></use></svg>`;

export function createViews(ctx) {
  const { state:s, t, b, money, num } = ctx;
  const comparison=createComparisonViews({...ctx,esc,icon});
  const go = (route,label,primary=false) => `<a class="button ${primary?'button-primary':'button-secondary'}" href="#${route}">${esc(label)}${icon(s.lang==='ar'?'arrow-left':'arrow-right')}</a>`;
  const pill = (label,kind='pending') => `<span class="pill pill-${kind}">${esc(label)}</span>`;
  const source = (url,label=t('Primary source','المصدر الأصلي')) => url ? `<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}${icon('arrow-up-right')}</a>` : '';
  const head = (title,intro,action='') => `<header class="page-head"><div><h1 id="page-title" tabindex="-1">${esc(title)}</h1><p class="page-intro">${esc(intro)}</p></div>${action}</header>`;
  const metric = (label,value,note='',cls='') => `<div class="metric ${cls}"><span class="metric-label">${esc(label)}</span><strong class="metric-value">${String(value).replace(/ (SAR|ر\.س)$/,' <span class="metric-currency">$1</span>')}</strong>${note?`<span class="metric-note">${esc(note)}</span>`:''}</div>`;
  const field = (scope,key,label,value,opt={}) => `<div class="field"><label class="field-label" for="${scope}-${key}">${esc(label)}${opt.tag?pill(opt.tag,'assumption'):''}</label><span class="number-shell"><input class="number-input" id="${scope}-${key}" name="${key}" data-model="${scope}" type="number" inputmode="decimal" min="${opt.min??0}" ${opt.max!=null?`max="${opt.max}"`:''} step="${opt.step??1}" value="${esc(value)}" ${opt.note?`aria-describedby="${scope}-${key}-help"`:''}>${opt.unit?`<span class="input-unit" aria-hidden="true">${esc(opt.unit)}</span>`:''}</span>${opt.note?`<span class="field-note" id="${scope}-${key}-help">${esc(opt.note)}</span>`:''}</div>`;
  const sectionHead = (title,copy='',action='') => `<div class="section-head"><div><h2 class="section-title">${esc(title)}</h2>${copy?`<p class="muted">${esc(copy)}</p>`:''}</div>${action}</div>`;
  const platformName = id => R.platforms.find(p=>p.id===id)?.name || t('Undecided — resolve trial evidence','لم يُحسم — راجع أدلة الاختبار');
  const gateStatus = id => s.gates[id]?.status || 'pending';
  const countVerified = () => R.gates.filter(g=>gateStatus(g.id)==='verified').length;
  const statusLabel = status => ({pending:t('Unverified','لم يُتحقق'),progress:t('In progress','قيد العمل'),verified:t('Marked verified','تم تأكيده محلياً'),blocked:t('Blocked','متعثر')})[status] || status;
  const statuses = (selected,attr) => `<select class="select-input" ${attr}>${['pending','progress','verified','blocked'].map(v=>`<option value="${v}" ${v===selected?'selected':''}>${esc(statusLabel(v))}</option>`).join('')}</select>`;
  const nextGate = () => R.gates.find(g=>gateStatus(g.id)!=='verified');
  const bar = (label,value,max,kind='',caption='') => `<div class="chart-row"><span class="chart-label">${esc(label)}</span><div class="chart-track"><span class="chart-fill ${kind}" style="transform:scaleX(${Math.min(1,Math.abs(value)/(max||1))})"></span></div><strong class="chart-value">${money(value)}</strong>${caption?`<small>${esc(caption)}</small>`:''}</div>`;

  function overview() {
    const gate=nextGate(), p=portfolioCosts(s.portfolio), u=unitEconomics(s.unit,p.annualOperating/12), n=countVerified();
    return `<section class="hero-grid"><div class="hero-copy"><span class="eyebrow">${t('NURIMI / FOUNDER DESK','نوريمي / مكتب المؤسس')}</span><h1 id="page-title" class="display-title" tabindex="-1">${t('One good store.<br>A repeatable business.','ابدأ بمتجر ناجح.<br>وابنِ عليه.')}</h1><p class="lead">${t('Make the first Saudi store work. Then carry the best parts into every brand after it.','أنجح تجربة المتجر الأول في السعودية، ثم انقل ما أثبت نجاحه إلى العلامات التالية.')}</p><div class="hero-actions">${go('launch',t('Find the next move','حدّد الخطوة التالية'),true)}${go('economics',t('Test the numbers','اختبر الأرقام'))}</div><div class="hero-context">${pill(t('Own inventory','مخزوننا الخاص'),'owner')}${pill(t('Saudi fulfilment','تنفيذ داخل السعودية'),'owner')}${pill(t('Merchant setup pending','إعداد التاجر لم يُحسم'))}</div></div><div class="hero-art"><div class="hero-art-wordmark">nurimi<span>.</span></div><img class="hero-photo photo-one" src="assets/p013.webp" width="1024" height="1024" alt="${t('Anua cleansing oil in the NURIMI visual direction','زيت تنظيف أنوا ضمن التوجه البصري لنوريمي')}"><img class="hero-photo photo-two" src="assets/p004.webp" width="1024" height="1024" alt="${t('Arencia vitamin C product scene','مشهد منتج فيتامين سي من أرينسيا')}"><div class="hero-caption"><span>${t('THE FIRST STORE','المتجر الأول')}</span><strong>NURIMI</strong><span>${t('Brand direction exists.<br>Commerce proof comes next.','التوجه البصري موجود.<br>والخطوة التالية إثبات التشغيل.')}</span></div></div></section>
      <div class="decision-strip"><div class="decision-strip-title">${icon('layers')}<div><span class="fine">${t('TWO OBJECTIVES / THREE PATHS','هدفان / ثلاثة مسارات')}</span><strong>${t('Fast first sale. Owned brand platform.','بيع سريع. أو أساس نملكه للعلامات.')}</strong></div></div><p>${t('Managed commerce optimises launch speed. A custom storefront or owned commerce core changes what we control and operate. Prove the risky parts before choosing.','التجارة المُدارة تختصر الإطلاق. الواجهة الخاصة أو نواة التجارة المملوكة تغيّر ما نتحكم فيه وما نشغّله. أثبت الأجزاء الأصعب قبل الاختيار.')}</p>${go('build',t('Compare build paths','قارن مسارات البناء'))}</div>
      <div class="grid-4 overview-metrics">${metric(t('Catalogue variants','متغيرات الكتالوج'),'23',t('All commercial fields still pending','البيانات التجارية ما زالت معلّقة'))}${metric(t('Proposed launch gates','متطلبات الإطلاق المقترحة'),`${n}<span class="metric-denominator"> / ${R.gates.length}</span>`,t('Your local evidence tracker','متابعة محلية لأدلتك'))}${metric(t('Per-order contribution','مساهمة الطلب'),money(u.contributionAfterCAC,2),t('Editable scenario, after acquisition','سيناريو قابل للتعديل، بعد الاستحواذ'),u.contributionAfterCAC<0?'negative':'')}${metric(t('Managed example / annual','مثال مُدار / سنوي'),money(p.annualOperating),t('Separate from custom build estimate','مستقل عن تقدير البناء الخاص'))}</div>
      <section class="grid-2"><article class="panel next-step"><div class="inline">${pill(t('Start here','ابدأ هنا'))}<span class="fine">${t('CRITICAL PATH','المسار الحاسم')}</span></div><h2>${gate?esc(b(gate.title)):t('Review the evidence','راجع الأدلة')}</h2><p>${gate?esc(b(gate.why)):t('All gates are marked verified locally. Confirm their evidence before releasing.','جميع المتطلبات مؤكدة محلياً. راجع أدلتها قبل الإطلاق.')}</p><div class="inline">${go('launch',t('Open launch map','افتح خريطة الإطلاق'),true)}<span class="fine">${t('Accountable:','المسؤول:')} ${gate?esc(b(gate.owner)):t('Founder','المؤسس')}</span></div></article><article class="panel panel-soft"><h2>${t('A decision tool, not a sales pitch.','أداة لاتخاذ القرار، لا عرض تسويقي.')}</h2><p>${t('Change the priorities. Pressure-test margins. Record what would make you switch platforms. The recommendation should survive your numbers.','غيّر الأولويات، واختبر الهوامش، وسجّل ما قد يدفعك لتغيير المنصة. يجب أن تصمد التوصية أمام أرقامك.')}</p><ul class="audit-list"><li>${t('Sourced facts have dates and limits.','الحقائق الموثقة مرتبطة بتاريخ وحدود.')}</li><li>${t('Estimates stay separate from quotations.','التقديرات منفصلة عن عروض الأسعار.')}</li><li>${t('A checked box is your record, not an external audit.','تأكيد المتطلب سجل منك، وليس تدقيقاً خارجياً.')}</li></ul>${go('evidence',t('Inspect the evidence','راجع الأدلة'))}</article></section>
      <section>${sectionHead(t('Work through the decisions','اعمل على القرارات'),t('A clear route from this prototype to the next brand.','مسار واضح من النموذج الحالي إلى العلامة التالية.'))}<div class="route-list">${[['build',t('Choose what we build','حدد ما سنبنيه'),t('Managed, hybrid and owned paths; delivery phases and budgets','مسارات مُدارة وهجينة ومملوكة ومراحل تنفيذ وميزانيات')],['stack',t('Choose a foundation','اختر الأساس'),t('Weighted comparison + full technology responsibilities','مقارنة مرجّحة ومسؤوليات المنظومة التقنية')],['economics',t('Find a viable order','اعثر على طلب مجدٍ'),t('Contribution, acquisition limits and portfolio costs','المساهمة وحدود الاستحواذ وتكاليف المتاجر')],['factory',t('Repeat with control','كرّر التجربة بانضباط'),t('Two brand configurations + stock allocation','إعدادات لعلامتين وتخصيص المخزون')]].map(([id,title,copy],i)=>`<a class="route-card" href="#${id}"><span class="badge-number">0${i+1}</span><div><h3>${title}</h3><p>${copy}</p></div>${icon(s.lang==='ar'?'arrow-left':'arrow-right')}</a>`).join('')}</div></section>`;
  }

  function market() {
    return `${head(t('Demand exists. Our advantage needs proof.','الطلب موجود. وميزتنا تحتاج إلى إثبات.'),t('Read the market without turning category adoption into a forecast for NURIMI.','اقرأ السوق دون تحويل انتشار الفئة إلى توقعات خاصة بنوريمي.'))}<div class="signal-grid">${R.signals.map((v,i)=>`<article class="panel signal-card ${i===0?'signal-large':''}"><span class="fine">${esc(b(v.period))}</span><strong class="signal-value">${esc(v.value)}</strong><h2>${esc(b(v.label))}</h2><p>${esc(b(v.meaning))}</p><div class="source-limit">${esc(b(v.limit))}</div>${source(v.url)}</article>`).join('')}</div><section>${sectionHead(t('What would make someone choose us?','لماذا قد يختارنا العميل؟'),t('Three hypotheses to test with shoppers and delivered orders.','ثلاث فرضيات نختبرها مع العملاء والطلبات المسلّمة.'))}<div class="grid-3">${[[t('Clarity earns trust','الوضوح يبني الثقة'),t('Exact packaging, useful Arabic explanations and visible delivery/return terms make choice easier.','عبوة مطابقة وشرح عربي مفيد وشروط توصيل وإرجاع واضحة تجعل الاختيار أسهل.'),t('Observe product-choice tasks; record confusion and unanswered questions.','راقب اختيار المنتجات وسجّل نقاط الالتباس والأسئلة التي لم تجد إجابة.')],[t('Local fulfilment improves the order','التنفيذ المحلي يحسّن الطلب'),t('A Saudi warehouse can support a credible delivery promise if stock, dispatch and returns are controlled.','يدعم المستودع السعودي وعداً موثوقاً بالتوصيل عندما ننضبط في المخزون والإرسال والإرجاع.'),t('Run parcel, damage, refusal and return drills before making promises.','اختبر الشحنات والتلف ورفض الاستلام والإرجاع قبل تقديم الوعود.')],[t('Repeat purchase supports growth','تكرار الشراء يدعم النمو'),t('Useful assortment and dependable operations must produce contribution after acquisition.','يجب أن تحقق التشكيلة المفيدة والتشغيل الموثوق مساهمة بعد تكلفة الاستحواذ.'),t('Follow delivered-order cohorts through a plausible replenishment cycle.','تابع شرائح الطلبات المسلّمة خلال دورة مناسبة لإعادة الشراء.')]].map(([title,copy,test])=>`<article class="panel"><span class="pill pill-assumption">${t('Hypothesis','فرضية')}</span><h3>${title}</h3><p>${copy}</p><p class="fine">${test}</p></article>`).join('')}</div></section><div class="panel panel-accent"><h2>${t('The metric to protect: contribution, not revenue alone.','المؤشر الذي نحميه: مساهمة الطلب، لا الإيراد وحده.')}</h2><p>${t('Nice One reported about SAR188m revenue and SAR20m net loss in Q2 2026. Scale does not make acquisition and fulfilment free.','أعلنت نايس ون إيراداً يقارب 188 مليون ريال وصافي خسارة يقارب 20 مليون ريال في الربع الثاني 2026. كبر المبيعات لا يلغي تكلفة الاستحواذ والتنفيذ.')}</p>${source('https://ir.niceonesa.com/',t('Nice One investor results','نتائج نايس ون للمستثمرين'))}${go('economics',t('Test our contribution','اختبر مساهمتنا'))}</div>`;
  }

  function stack() {
    const id=s.stackInspect, platform=R.platforms.find(p=>p.id===id)||R.platforms[0];
    return `${head(t('Pick the foundation. Own the trade-offs.','اختر الأساس وافهم تبعاته.'),t('Scores screen vendors; Build paths explains what we actually build, own and operate. A high score is not a delivery plan.','الدرجات تفرز المورّدين؛ ومسارات البناء توضّح ما نبنيه ونملكه ونشغّله. الدرجة المرتفعة ليست خطة تنفيذ.'),go('build',t('Open build paths','افتح مسارات البناء')))}<div class="tabs" role="group" aria-label="${t('Stack view','عرض المنظومة')}"><button class="tab ${s.stackTab==='compare'?'is-active':''}" data-action="stack-tab" data-tab="compare" aria-pressed="${s.stackTab==='compare'}">${t('Compare routes','قارن المسارات')}</button><button class="tab ${s.stackTab==='blueprint'?'is-active':''}" data-action="stack-tab" data-tab="blueprint" aria-pressed="${s.stackTab==='blueprint'}">${t('Managed reference blueprint','مرجع المسار المُدار')}</button></div>${s.stackTab==='blueprint'?blueprint():`<div class="grid-2 stack-layout"><section class="panel"><div class="section-head"><h2>${t('What matters most?','ما الأهم بالنسبة لك؟')}</h2><button class="button button-ghost" data-action="reset-weights">${t('Reset','إعادة الضبط')}</button></div><div class="preset-row">${[['saudi',t('Saudi launch','إطلاق سعودي')],['global',t('International reach','امتداد دولي')],['ownership',t('Platform ownership','امتلاك المنظومة')]].map(([id,label])=>`<button class="preset" data-action="weight-preset" data-preset="${id}">${label}</button>`).join('')}</div><div class="weight-controls">${R.criteria.map(c=>`<label class="weight-control" for="weight-${c.id}"><span class="weight-title">${esc(b(c.label))}<output data-weight-output="${c.id}" for="weight-${c.id}">${num(s.weights[c.id])}</output></span><input class="range-input" id="weight-${c.id}" type="range" min="0" max="50" step="1" value="${s.weights[c.id]}" data-weight="${c.id}" aria-describedby="weight-note-${c.id}"><small class="fine" id="weight-note-${c.id}">${esc(b(c.description))}</small></label>`).join('')}</div><p class="fine" id="weight-total"></p></section><section class="panel panel-soft"><div class="section-head"><h2>${t('Weighted shortlist','القائمة المرجّحة')}</h2>${pill(t('Judgement / 10','تقدير / 10'),'assumption')}</div><div id="platform-ranking"></div><p class="fine">${t('Small score differences are not measured vendor advantages. A failed hard gate overrides a high score.','فروق الدرجات الصغيرة ليست تفوقاً مقاساً للمورّد. فشل متطلب حاسم يتقدم على الدرجة المرتفعة.')}</p><div class="rule"></div><label class="field" for="stack-inspect"><span class="field-label">${t('Inspect a route','راجع مساراً')}</span><select class="select-input" id="stack-inspect" data-action="inspect-platform">${R.platforms.map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div id="platform-detail">${platformDetail(platform)}</div></section></div>`}`;
  }

  function platformDetail(p) {
    const tests=[['merchant',t('Merchant + payment eligibility','أهلية التاجر والدفع')],['theme',t('Required theme + licence','الثيم المطلوب والترخيص')],['operations',t('Order, stock + refund proof','إثبات الطلب والمخزون والاسترداد')]];
    return `<div class="platform-detail"><span class="fine">${t('ROUTE INSPECTION','مراجعة المسار')}</span><h2>${esc(p.name)}</h2><p>${esc(b(p.tagline))}</p><div class="pricing-note">${esc(b(p.pricing))}</div><div class="grid-2"><div><h3>${t('Why consider it','أسباب اختياره')}</h3><ul>${p.strengths.map(v=>`<li>${esc(b(v))}</li>`).join('')}</ul></div><div><h3>${t('What can change the decision','ما قد يغيّر القرار')}</h3><ul>${p.limits.map(v=>`<li>${esc(b(v))}</li>`).join('')}</ul></div></div><details class="details"><summary>${t('Evidence needed before commitment','الأدلة المطلوبة قبل الالتزام')}</summary><ul>${p.proof.map(v=>`<li>${esc(b(v))}</li>`).join('')}</ul></details><h3>${t('Your trial record','سجل تجربتك')}</h3><p class="fine">${t('Local founder marks only. No merchant account is connected.','تأكيدات محلية من المؤسس. لا يوجد اتصال بحساب تاجر.')}</p><div class="trial-controls">${tests.map(([key,label])=>`<label class="field"><span class="field-label">${label}</span><select class="select-input" data-platform-gate="${p.id}" data-gate-key="${key}">${[['unknown',t('Not tested','لم يُختبر')],['pass',t('Founder marked pass','أكد المؤسس اجتيازه')],['fail',t('Failed — excludes route','فشل — يستبعد المسار')]].map(([value,text])=>`<option value="${value}" ${s.platformGates[p.id]?.[key]===value?'selected':''}>${text}</option>`).join('')}</select></label>`).join('')}</div><button class="button button-primary" data-action="choose-platform" data-platform="${p.id}" ${Object.values(s.platformGates[p.id]||{}).includes('fail')?'disabled aria-describedby="route-blocked-note"':''}>${t('Record as preferred route','سجّله كمسار مفضّل')}</button>${Object.values(s.platformGates[p.id]||{}).includes('fail')?`<p class="gate-caution" id="route-blocked-note">${t('Resolve the failed hard gate before recording this route.','عالج فشل المتطلب الحاسم قبل تسجيل هذا المسار.')}</p>`:''}<div class="source-inline">${p.sources.map(v=>source(v.url,v.title)).join('')}</div></div>`;
  }

  function blueprint() {
    return `<div class="panel panel-accent"><h2>${t('Managed commerce. Reusable brand layer.','تجارة مُدارة وطبقة علامة قابلة لإعادة الاستخدام.')}</h2><p>${t('This table describes the managed Salla reference only. Hybrid and owned implementations have their own technology and delivery maps in Build paths.','يصف الجدول مرجع سلة المُدار فقط. للمسارين الهجين والمملوك خرائط تقنية وتنفيذ مستقلة في مسارات البناء.')}</p><div class="flow-steps">${[t('Brand + approved product data','الهوية وبيانات المنتجات المعتمدة'),t('Supported native storefront','واجهة أصلية مدعومة'),t('Platform checkout + orders','دفع وطلبات المنصة'),t('Saudi warehouse + carrier','مستودع وناقل داخل السعودية'),t('Reconcile + learn','طابق السجلات وتعلّم')].map((v,i)=>`<div><span>${i+1}</span><strong>${v}</strong></div>`).join('')}</div></div><div class="table-wrap"><table class="data-table"><caption>${t('Full technology and operating responsibility map','خريطة التقنية والمسؤوليات التشغيلية')}</caption><thead><tr><th scope="col">${t('Layer','الطبقة')}</th><th scope="col">${t('Technology / responsibility','التقنية والمسؤولية')}</th><th scope="col">${t('Owner / evidence','المسؤول والدليل')}</th></tr></thead><tbody>${R.stackLayers.map(l=>`<tr><th scope="row">${esc(b(l.label))}</th><td><strong>${esc(b(l.technology))}</strong><p>${esc(b(l.responsibility))}</p></td><td><strong>${esc(b(l.owner))}</strong><p class="fine">${esc(b(l.evidence))}</p>${source(l.url)}</td></tr>`).join('')}</tbody></table></div><div class="grid-2"><div class="panel"><h2>${t('The React opportunity','فرصة React')}</h2><p>${t('Salla documents a managed React/TanStack theme engine. Our local install trial was inconclusive because of registry/network errors; it neither proves a package defect nor production readiness. Keep it as a separate spike until a clean build, merchant install, bilingual checkout and rollback pass.','توثّق سلة محرك ثيمات مُداراً باستخدام React وTanStack. لم تحسم تجربة التثبيت المحلية بسبب أخطاء الشبكة والسجل؛ فلا تثبت عيباً في الحزمة أو جاهزية للإنتاج. اختبره منفصلاً حتى ينجح البناء والتثبيت والدفع باللغتين والتراجع.')}</p>${source('https://docs.salla.dev/twilight/react/start/what-is-a-theme')}</div><div class="panel"><h2>${t('Add infrastructure when the work requires it','أضف البنية التقنية عند الحاجة الفعلية')}</h2><p>${t('Start with native search, authentication, checkout and order operations. Add a database, integration service or shared WMS only for a measured need with an accountable maintenance owner.','ابدأ بالبحث والدخول والدفع وإدارة الطلبات داخل المنصة. أضف قاعدة بيانات أو خدمة تكامل أو نظام مخزون مشتركاً عندما تثبت الحاجة ويتحدد مسؤول صيانته.')}</p></div></div>`;
  }

  const unitFields = () => [
    ['basket',t('Product basket, VAT-inclusive if registered','قيمة المنتجات، شاملة الضريبة إن كنت مسجلاً'),{step:1,unit:t('SAR','ر.س')}],
    ['shippingCollected',t('Shipping charged to customer','الشحن المحصّل من العميل'),{unit:t('SAR','ر.س')}],
    ['cogs',t('Landed goods cost','تكلفة المنتجات الواصلة'),{unit:t('SAR','ر.س'),note:t('Exclude recoverable VAT from costs in this scenario.','استبعد الضريبة القابلة للاسترداد من تكاليف هذا السيناريو.')}],
    ['pspPercent',t('Payment processing rate','نسبة معالجة الدفع'),{step:.1,max:100,unit:'%'}],
    ['pspFlat',t('Payment fixed charge','رسم الدفع الثابت'),{step:.1,unit:t('SAR','ر.س')}],
    ['carrierCost',t('Carrier cost per order','تكلفة الناقل لكل طلب'),{unit:t('SAR','ر.س')}],
    ['pickPack',t('Pick and pack labour','عمل التجهيز والتعبئة'),{unit:t('SAR','ر.س')}],
    ['packaging',t('Packaging materials','مواد التغليف'),{unit:t('SAR','ر.س')}],
    ['reserve',t('Return / refusal / spoilage reserve','مخصص الإرجاع والرفض والتلف'),{unit:t('SAR','ر.س')}],
    ['cac',t('Delivered-order acquisition cost','تكلفة الاستحواذ للطلب المسلّم'),{unit:t('SAR','ر.س')}],
    ['platformFeePercent',t('Additional platform transaction fee','نسبة عمولة المنصة الإضافية'),{step:.1,max:100,unit:'%',note:t('Separate from PSP fees. Verify exact contract and fee base.','منفصلة عن رسوم مزود الدفع. تحقّق من العقد وأساس احتسابها.')}],
  ];

  function economics() {
    return `${head(t('Does each order earn its place?','هل يحقق كل طلب مساهمة مجدية؟'),t('A live scenario model. Replace every assumption with quotations and observed delivered-order data.','نموذج سيناريو مباشر. استبدل كل افتراض بعرض سعر أو بيانات طلبات مسلّمة فعلية.'),`<button class="button button-secondary" data-action="save-scenario">${icon('plus')}${t('Save scenario','احفظ السيناريو')}</button>`)}<div class="compare-ready-note"><p>${t('Unit contribution uses your order assumptions; its fixed-cost context now follows the selected Build comparison plan. The portfolio tab retains the initial managed-store example with its own assumptions. Do not add the two technical budgets.','مساهمة الطلب تعتمد افتراضاتك، وسياق التكاليف الثابتة يتبع الآن خطة البناء المختارة في المقارنة. يحتفظ تبويب المتاجر بمثال المتجر المُدار الأول وافتراضاته. لا تجمع الميزانيتين التقنيتين.')}</p>${go('build',t('Compare the delivery budgets','قارن ميزانيات التنفيذ'))}</div><div class="tabs" role="group" aria-label="${t('Economics view','عرض الجدوى')}">${[['unit',t('One order','طلب واحد')],['portfolio',t('One to many stores','من متجر إلى عدة متاجر')]].map(([id,label])=>`<button class="tab ${s.econTab===id?'is-active':''}" data-action="econ-tab" data-tab="${id}" aria-pressed="${s.econTab===id}">${label}</button>`).join('')}</div>${s.econTab==='unit'?unitView():portfolioView()}<section class="scenario-section">${sectionHead(t('Your saved scenarios','سيناريوهاتك المحفوظة'),t('Stored on this browser. Export a workspace file to move them.','محفوظة في هذا المتصفح. صدّر ملف المكتب لنقلها.'))}<div class="scenario-list">${s.scenarios.length?s.scenarios.map((v,i)=>`<div class="scenario-item"><div><strong>${esc(v.name)}</strong><span class="fine">${money(unitEconomics(v.unit).contributionAfterCAC,2)} ${t('after acquisition','بعد الاستحواذ')} · ${num(v.portfolio.stores)} ${t('store(s)','متجر')}</span></div><button class="button button-secondary" data-action="load-scenario" data-index="${i}">${t('Load','استخدم')}</button><button class="icon-button" data-action="delete-scenario" data-index="${i}" aria-label="${esc(t('Delete scenario ','حذف السيناريو ')+v.name)}">${icon('x')}</button></div>`).join(''):`<p class="empty-state">${t('Save a base case, then test the assumptions that could change the decision.','احفظ السيناريو الأساسي، ثم اختبر الافتراضات التي قد تغيّر القرار.')}</p>`}</div></section>`;
  }

  function unitView() {
    return `<div class="preset-row">${[['base',t('Research example','مثال البحث')],['squeeze',t('Margin squeeze','ضغط الهامش')],['organic',t('Lower acquisition cost','استحواذ أقل تكلفة')]].map(([id,label])=>`<button class="preset" data-action="unit-preset" data-preset="${id}">${label}</button>`).join('')}<span class="fine">${t('Illustrative scenarios, not forecasts.','سيناريوهات توضيحية وليست توقعات.')}</span></div><div class="economics-layout"><section class="panel controls-panel"><div class="section-head"><h2>${t('Order assumptions','افتراضات الطلب')}</h2>${pill(t('Editable assumptions','افتراضات قابلة للتعديل'),'assumption')}</div><div class="vat-control"><label class="check-control"><input type="checkbox" data-model="unit" name="vatRegistered" ${s.unit.vatRegistered?'checked':''}><span>${t('Model a VAT-registered merchant','نمذجة تاجر مسجل في الضريبة')}</span></label>${field('unit','vatRate',t('VAT rate','نسبة الضريبة'),s.unit.vatRate,{max:100,unit:'%'})}</div><p class="field-note">${t('Scenario setting only. NURIMI’s registration status is unconfirmed. Costs below exclude recoverable VAT.','إعداد للسيناريو فقط. تسجيل نوريمي غير مؤكد. التكاليف أدناه تستبعد الضريبة القابلة للاسترداد.')}</p><div class="control-grid">${unitFields().map(([key,label,opt])=>field('unit',key,label,s.unit[key],opt)).join('')}</div></section><div class="stack"><section class="panel panel-dark unit-result"><span class="fine">${t('LEFT AFTER ACQUISITION','المتبقي بعد الاستحواذ')}</span><strong class="result-number" id="unit-profit">—</strong><p id="unit-verdict"></p><div class="grid-2 result-secondary"><div><span>${t('Before acquisition','قبل الاستحواذ')}</span><strong id="unit-before">—</strong></div><div><span>${t('Break-even CAC','حد الاستحواذ للتعادل')}</span><strong id="unit-max-cac">—</strong></div></div></section><section class="panel"><h2>${t('Where the order goes','أين تذهب قيمة الطلب؟')}</h2><div id="unit-waterfall" class="waterfall" aria-label="${t('Order contribution breakdown','تفصيل مساهمة الطلب')}"></div><details class="details"><summary>${t('Show the calculation','اعرض المعادلة')}</summary><p id="unit-formula" class="formula"></p><p class="fine">${t('Customer shipping enters revenue; the full carrier cost is deducted once. Payment and platform percentages use the charged total. This simplified model does not replace tax accounting.','يدخل شحن العميل ضمن الإيراد، وتُخصم تكلفة الناقل كاملة مرة واحدة. نسب الدفع والمنصة على إجمالي المبلغ المحصّل. هذا نموذج مبسّط لا يحل محل المحاسبة الضريبية.')}</p></details></section><section class="panel panel-soft"><h2>${t('What if acquisition gets harder?','ماذا لو ارتفعت تكلفة الاستحواذ؟')}</h2><div id="cac-sensitivity" class="bar-chart"></div><p class="fine" id="unit-fixed-context"></p></section></div></div>`;
  }

  function portfolioView() {
    const f=(key,en,ar,opt={})=>field('portfolio',key,t(en,ar),s.portfolio[key],opt);
    return `<div class="economics-layout"><section class="panel controls-panel"><div class="section-head"><h2>${t('Build a portfolio budget','ابنِ ميزانية المتاجر')}</h2>${pill(t('Planning model','نموذج تخطيط'),'assumption')}</div>${f('stores','Number of stores','عدد المتاجر',{min:1,max:10})}<div class="control-grid">${f('planAnnual','Annual plan per store','اشتراك سنوي لكل متجر',{note:t('Research Salla Pro list: SAR2,990; replace with tax-confirmed quote.','قائمة سلة برو في البحث: 2,990 ريال. استبدلها بعرض مؤكد ضريبياً.')})}${f('domainAnnual','Annual domain allowance','مخصص النطاق السنوي')}${f('appsAnnual','Apps / monitoring per year','التطبيقات والمراقبة سنوياً')}${f('themePerStore','Initial theme licence allowance','مخصص ترخيص الثيم الأولي')}</div><details class="details" open><summary>${t('People and recurring care','الفريق والمتابعة الدورية')}</summary><div class="control-grid">${f('engineeringRate','Engineering hourly rate','تكلفة ساعة الهندسة')}${f('operationsRate','Operations hourly rate','تكلفة ساعة التشغيل')}${f('sharedHoursMonthly','Shared technical hours / month','ساعات تقنية مشتركة شهرياً')}${f('storeHoursMonthly','Extra technical hours / store / month','ساعات تقنية لكل متجر شهرياً')}${f('controlHoursMonthly','Control/export hours / store / month','ساعات رقابة وتصدير لكل متجر شهرياً')}</div></details><details class="details"><summary>${t('Launch labour assumptions','افتراضات عمل الإطلاق')}</summary><div class="control-grid">${f('firstEngineeringHours','First store engineering hours','ساعات هندسة المتجر الأول')}${f('firstDesignHours','First store design QA hours','ساعات مراجعة التصميم للأول')}${f('designRate','Design hourly rate','تكلفة ساعة التصميم')}${f('firstOperationsHours','First store operations hours','ساعات تشغيل المتجر الأول')}${f('extraEngineeringHours','Engineering hours / additional brand','ساعات هندسة لكل علامة إضافية')}${f('extraOperationsHours','Operations/QA hours / additional brand','ساعات تشغيل ومراجعة لكل علامة إضافية')}</div></details></section><div class="stack"><section class="panel panel-dark"><span class="fine">${t('FIRST-YEAR PLANNING ALLOWANCE','مخصص تخطيط السنة الأولى')}</span><strong class="result-number" id="portfolio-year">—</strong><p>${t('Setup + one year of software and modelled technical/control work.','التأسيس مع سنة من البرمجيات والعمل التقني والرقابي المفترض.')}</p><div class="grid-2 result-secondary"><div><span>${t('Initial setup','التأسيس')}</span><strong id="portfolio-setup">—</strong></div><div><span>${t('Annual operation','التشغيل السنوي')}</span><strong id="portfolio-operating">—</strong></div></div></section><section class="panel"><h2>${t('Recurring costs, made visible','التكاليف المتكررة بوضوح')}</h2><div id="portfolio-breakdown"></div><div class="rule"></div><p class="fine">${t('Excludes inventory, marketing, PSP fees, shipping, customer-service workload, taxes if additional and unquoted accounting/WMS. Theme allowance is an assumption, not a licence quote.','لا يشمل المخزون والتسويق ورسوم الدفع والشحن وعمل دعم العملاء والضرائب الإضافية والمحاسبة أو نظام المخزون غير المسعّر. مخصص الثيم افتراض وليس عرض ترخيص.')}</p></section><section class="panel panel-soft"><h2>${t('The cost of repeating','تكلفة التكرار')}</h2><div id="portfolio-scaling" class="bar-chart"></div><p class="fine" id="portfolio-hours"></p></section></div></div>`;
  }

  function launch() {
    const n=countVerified();
    return `<div class="build-overview-prompt"><div><h2>${t('Retail prerequisites apply to every route.','متطلبات التجزئة تخص كل المسارات.')}</h2><p>${t('This checklist began with the managed-store plan; theme entitlement applies to that path. Custom build acceptance also requires the payment adapter, restore, event and isolation evidence in Build paths.','بدأت القائمة بخطة المتجر المُدار؛ ترخيص الثيم يخص ذلك المسار. قبول البناء الخاص يحتاج أيضاً أدلة محول الدفع والاستعادة والأحداث والعزل في مسارات البناء.')}</p></div>${go('build',t('Custom implementation plan','خطة التنفيذ الخاصة'))}</div>${head(t('Earn the right to launch.','استوفِ متطلبات الإطلاق.'),t('Your merchant setup is unconfirmed. Saudi fulfilment is selected. Work through dependencies before promising a date.','إعداد التاجر غير مؤكد، والتنفيذ داخل السعودية هو المسار المختار. احسم الاعتماديات قبل الوعد بموعد.'),`<button class="button button-secondary" data-action="export">${icon('download')}${t('Take the plan','صدّر الخطة')}</button>`)}<section class="panel launch-summary"><div><span class="fine">${t('FOUNDER-MARKED GATES','المتطلبات المؤكدة محلياً')}</span><strong class="launch-count">${n}<span> / ${R.gates.length}</span></strong><p>${t('Self-reported progress; keep evidence with each mark.','تقدم تسجّله بنفسك؛ أرفق دليل كل تأكيد.')}</p></div><div><strong class="metric-value">72–112 <span class="fine">${t('engineering hours','ساعة هندسة')}</span></strong><p>${t('2–3 elapsed working weeks after complete inputs. Onboarding and provider review are additional, unbounded here.','نحو 2–3 أسابيع عمل بعد اكتمال المدخلات. التأهيل ومراجعة المورّد مدة إضافية غير محددة هنا.')}</p></div><div>${field('state','verifiedSkus',t('Verified variants reported by you','متغيرات تحقّقت منها وأكدتها'),s.verifiedSkus,{max:23})}<p class="fine">${t('Original source audit: 0/23 pass the proposed publication gate.','تدقيق المصدر الأصلي: 0 من 23 يجتاز متطلب النشر المقترح.')}</p></div></section><section>${sectionHead(t('Sequence the work','رتّب العمل'),t('Role-based effort estimates. External waiting is separate.','تقديرات جهد بحسب المسؤولية. الانتظار الخارجي منفصل.'))}<ol class="phase-list">${R.phases.map((p,i)=>`<li class="phase-card"><span class="phase-number">${String(i+1).padStart(2,'0')}</span><div class="phase-body"><h3>${esc(b(p.title))}</h3><p>${esc(b(p.outcome))}</p><span class="fine">${esc(b(p.owner))}</span></div><span class="phase-hours">${p.hours?.[0]!=null?`${p.hours[0]}–${p.hours[1]} ${t('h','س')}`:t('Observe','مراقبة')}<small>${esc(b(p.effortLabel))}</small></span></li>`).join('')}</ol></section><section>${sectionHead(t('The evidence checklist','قائمة الأدلة'),t('Use “verified” only when you can name the evidence and accountable owner.','استخدم حالة «تم التأكيد» عندما يتوفر دليل ومسؤول واضح.'))}<div class="filter-row"><label class="field"><span class="field-label">${t('Filter gates','تصفية المتطلبات')}</span><select class="select-input" id="gate-filter"><option value="all">${t('All gates','جميع المتطلبات')}</option><option value="open">${t('Still open','لم تكتمل')}</option><option value="verified">${t('Marked verified','تم تأكيدها محلياً')}</option><option value="blocked">${t('Blocked','متعثرة')}</option></select></label></div><div class="gate-list" id="gate-list">${R.gates.map(g=>gateCard(g)).join('')}</div></section>`;
  }

  function gateCard(g) {
    const v=s.gates[g.id]||{};
    return `<article class="gate-card" id="gate-${g.id}" data-gate-card="${g.id}" data-status="${v.status||'pending'}"><div class="gate-head"><div><span class="fine">${esc(b(g.owner))}</span><h3>${esc(b(g.title))}</h3></div><label class="field gate-status-field"><span class="sr-only">${esc(b(g.title))} ${t('status','الحالة')}</span>${statuses(v.status||'pending',`data-gate-status="${g.id}"`)}</label></div><p>${esc(b(g.why))}</p><details class="details"><summary>${t('Acceptance criteria + evidence notes','معايير القبول وملاحظات الأدلة')}</summary><ul class="audit-list">${g.acceptance.map(v=>`<li>${esc(b(v))}</li>`).join('')}</ul><div class="grid-2"><label class="field"><span class="field-label">${t('Accountable owner','المسؤول المباشر')}</span><input class="number-input text-input" data-gate-owner="${g.id}" maxlength="100" value="${esc(v.owner||'')}" placeholder="${esc(b(g.owner))}"></label><label class="field"><span class="field-label">${t('Evidence / result / remaining issue','الدليل أو النتيجة أو النقطة المعلقة')}</span><textarea class="textarea" data-gate-evidence="${g.id}" maxlength="2000" rows="3">${esc(v.evidence||'')}</textarea></label></div><div class="source-inline">${g.sources.map(v=>source(v.url,v.title)).join('')}</div></details>${v.status==='verified'&&!v.evidence?`<p class="gate-caution">${t('Marked verified without an evidence note. Add the result for review.','تم تأكيده دون ملاحظة دليل. أضف النتيجة للمراجعة.')}</p>`:''}</article>`;
  }

  function factory() {
    const sada=s.factory.brand==='sada';
    return `${head(t('Keep the system. Change the brand.','احتفظ بالنظام وغيّر العلامة.'),t('A configuration workshop: shared capability, distinct identity, separate commercial records.','ورشة إعداد: قدرات مشتركة وهوية مستقلة وسجلات تجارية منفصلة.'))}<div class="grid-2 factory-layout"><section class="panel"><h2>${t('Try the second-brand test','جرّب اختبار العلامة الثانية')}</h2><div class="tabs" role="group" aria-label="${t('Brand fixture','نموذج العلامة')}"><button class="tab ${!sada?'is-active':''}" data-action="factory-brand" data-brand="nurimi" aria-pressed="${!sada}">NURIMI</button><button class="tab ${sada?'is-active':''}" data-action="factory-brand" data-brand="sada" aria-pressed="${sada}">SADA <span class="fine">${t('internal test','اختبار داخلي')}</span></button></div><p>${t('NURIMI is an editorial skincare retailer. SADA is a fictional, value-led body-care retailer using the two existing Mixa records. Manufacturer packaging stays unchanged.','نوريمي متجر عناية بالبشرة بطابع تحريري. سادة اختبار تخيّلي لمتجر عناية بالجسم يركز على القيمة ويستخدم سجلي ميكسا الموجودين. عبوات الشركات لا تتغيّر.')}</p><label class="field"><span class="field-label">${t('Retailer display name','اسم المتجر المعروض')}</span><input id="factory-name" class="number-input text-input" maxlength="40" value="${esc(s.factory.name|| (sada?'SADA':'NURIMI'))}"></label><label class="field"><span class="field-label">${t('Primary accent','اللون الأساسي')}</span><input id="factory-color" class="color-input" type="color" value="${s.factory.accent|| (sada?'#125c48':'#b82b55')}"></label><label class="field"><span class="field-label">${t('Page recipe','تركيبة الصفحة')}</span><select class="select-input" id="factory-layout"><option value="editorial" ${(s.factory.layout|| (sada?'compact':'editorial'))==='editorial'?'selected':''}>${t('Editorial discovery','اكتشاف تحريري')}</option><option value="compact" ${(s.factory.layout|| (sada?'compact':'editorial'))==='compact'?'selected':''}>${t('Compact / value first','مختصر يركز على القيمة')}</option></select></label><button class="button button-primary" data-action="export-brand">${icon('download')}${t('Export brand manifest','صدّر إعدادات العلامة')}</button><p class="fine">${t('Local preview only. No platform adapter, merchant deployment or launch-speed claim. Brand names and licences need separate clearance.','معاينة محلية فقط. لا تثبت تكامل المنصة أو نشر متجر أو سرعة إطلاق. الأسماء والتراخيص تحتاج إلى اعتماد منفصل.')}</p></section><section class="brand-preview" id="factory-preview"></section></div><section>${sectionHead(t('What should repeat?','ما الذي يتكرر؟'))}<div class="grid-3">${[[t('Shared source','مصدر مشترك'),t('Components, content schema, token format, product-detail patterns, tests and release procedures.','المكونات وبنية المحتوى والتوكنز وأنماط تفاصيل المنتج والاختبارات وإجراءات الإصدار.')],[t('Store-specific','خاص بكل متجر'),t('Seller, domain, bank, catalogue, prices, orders, customers, consent, stock and analytics.','البائع والنطاق والبنك والكتالوج والأسعار والطلبات والعملاء والموافقات والمخزون والتحليلات.')],[t('Controlled rollout','نشر منضبط'),t('Tag a release. Preview one store. Check it. Activate, then move to the next. Keep settings with the release.','حدّد إصداراً، وعاينه على متجر واحد واختبره، ثم فعّله وانتقل للتالي. احفظ الإعدادات مع الإصدار.')]].map(([title,copy])=>`<article class="panel"><h3>${title}</h3><p>${copy}</p></article>`).join('')}</div></section><section class="panel allocation-panel"><div class="section-head"><div><h2>${t('Ten units cannot become twenty.','عشر وحدات لا تصبح عشرين.')}</h2><p>${t('A stock-allocation explainer, not an inventory integration test.','شرح لتخصيص المخزون، وليس اختبار تكامل مخزون.')}</p></div>${pill(t('Illustrative','توضيحي'),'assumption')}</div><div class="grid-2"><div><label class="weight-control" for="allocation-range"><span class="weight-title">${t('Units allocated to NURIMI','الوحدات المخصصة لنوريمي')}<output id="allocation-primary" for="allocation-range">${s.allocation}</output></span><input class="range-input" id="allocation-range" type="range" min="0" max="10" step="1" value="${s.allocation}"></label><div id="allocation-visual"></div><p class="fine">${t('Separate store quantities must sum to the physical stock. A shared pool later needs an authoritative WMS/OMS with tested atomic allocation.','يجب أن يساوي مجموع كميات المتاجر المخزون الفعلي. المخزون المشترك لاحقاً يحتاج إلى نظام معتمد يختبر تخصيص الوحدات بصورة سليمة.')}</p></div><div class="panel-soft allocation-warning"><strong>10 + 10 ≠ 10</strong><p>${t('Advertising all ten units in both independent stores exposes ten units you do not have. Delayed webhook synchronisation does not guarantee safety.','عرض الوحدات العشر كاملة في متجرين مستقلين يعرض عشر وحدات غير موجودة. مزامنة الأحداث المتأخرة لا تضمن سلامة المخزون.')}</p></div></div></section><section class="panel"><h2>${t('Repeatability still needs a merchant proof.','التكرار ما زال يحتاج إلى تجربة متجر فعلية.')}</h2><p>${t('The research packager passed 19 local checks for two configurations. The next test is a separate merchant store, with licence costs, effort, stock isolation and regressions recorded. Target 16–32 engineering hours per additional brand after the first accepted release; measure before forecasting.','اجتازت أداة البحث 19 فحصاً محلياً لإعدادين. الاختبار التالي متجر تاجر منفصل مع تسجيل تكلفة الترخيص والجهد وعزل المخزون والأخطاء. التقدير 16–32 ساعة هندسة لكل علامة إضافية بعد قبول الأول؛ قِس قبل التوقع.')}</p>${go('launch',t('See the release gates','راجع متطلبات الإطلاق'))}</section>`;
  }

  function decisions() {
    return `${head(t('Leave with a decision.','اخرج بقرار واضح.'),t('Capture the choice, the reason and the evidence that could reverse it. Everything here stays on this browser until you export it.','سجّل الاختيار وسببه والدليل الذي قد يغيّره. يبقى كل ما هنا في هذا المتصفح إلى أن تصدّره.'),`<button class="button button-primary" data-action="export">${icon('download')}${t('Export founder brief','صدّر موجز المؤسس')}</button>`)}<div class="grid-2"><section class="panel"><h2>${t('Decision record','سجل القرار')}</h2>${comparison.decisionNotice()}<p class="compare-ready-note">${t('First compare delivery models, then choose a vendor/core for that model. A matching choice is not approval to launch.','قارن نماذج التنفيذ أولاً، ثم اختر المورّد أو المحرك المناسب. تطابق الاختيار لا يعني اعتماد الإطلاق.')}</p>${go('build',t('Compare managed vs custom','قارن المُدار والبناء الخاص'))}<div class="field"><label class="field-label" for="decision-build-model">${t('Delivery model under consideration','نموذج التنفيذ قيد الدراسة')}</label><select id="decision-build-model" class="select-input">${[['native',t('Managed store','متجر مُدار')],['hybrid',t('Custom storefront + managed commerce','واجهة خاصة وتجارة مُدارة')],['owned',t('Owned / custom commerce','تجارة نملكها / بناء خاص')]].map(([id,label])=>`<option value="${id}" ${s.build.route===id?'selected':''}>${esc(label)}</option>`).join('')}</select></div><div class="field"><label class="field-label" for="decision-platform">${t('Preferred platform / commerce engine','المنصة أو محرك التجارة المفضّل')}</label><select id="decision-platform" class="select-input" data-decision="platform"><option value="undecided" ${s.decisions.platform==='undecided'?'selected':''}>${t('Undecided — review trial evidence','لم يُحسم — راجع أدلة الاختبار')}</option>${R.platforms.map(p=>`<option value="${p.id}" ${s.decisions.platform===p.id?'selected':''} ${Object.values(s.platformGates[p.id]||{}).includes('fail')?'disabled':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label class="field-label" for="decision-launchMode">${t('Launch approach','أسلوب الإطلاق')}</label><select id="decision-launchMode" class="select-input" data-decision="launchMode"><option value="verified" ${s.decisions.launchMode==='verified'?'selected':''}>${t('Verified subset, controlled release','مجموعة متحقق منها وإطلاق منضبط')}</option><option value="full" ${s.decisions.launchMode==='full'?'selected':''}>${t('Full assortment after every SKU clears','كامل التشكيلة بعد تحقق كل منتج')}</option></select></div><div class="field"><label class="field-label" for="decision-review-date">${t('Decision review date','موعد مراجعة القرار')}</label><input id="decision-review-date" class="number-input" type="date" data-decision="reviewDate" value="${esc(s.decisions.reviewDate)}"></div><div class="field"><label class="field-label" for="decision-rationale">${t('Why this choice?','لماذا هذا الاختيار؟')}</label><textarea id="decision-rationale" class="textarea" data-decision="rationale" maxlength="3000" rows="5" placeholder="${t('What matters most to this business?','ما الأهم لهذا النشاط؟')}">${esc(s.decisions.rationale)}</textarea></div><div class="field"><label class="field-label" for="decision-reversal">${t('What evidence would change your mind?','ما الدليل الذي قد يغيّر رأيك؟')}</label><textarea id="decision-reversal" class="textarea" data-decision="reversal" maxlength="3000" rows="4" placeholder="${t('For example: payment failure, theme permission, total cost…','مثلاً: فشل الدفع أو صلاحيات الثيم أو التكلفة الكاملة…')}">${esc(s.decisions.reversal)}</textarea></div><div class="field"><label class="field-label" for="decision-nextAction">${t('Next action and accountable owner','الإجراء التالي ومسؤوله')}</label><textarea id="decision-nextAction" class="textarea" data-decision="nextAction" maxlength="2000" rows="3">${esc(s.decisions.nextAction)}</textarea></div></section><section class="panel panel-soft"><h2>${t('Decision snapshot','ملخص القرار')}</h2><dl class="decision-dl"><div><dt>${t('Build model','نموذج البناء')}</dt><dd>${s.build.route==='native'?t('Managed','مُدار'):s.build.route==='hybrid'?t('Hybrid','هجين'):t('Owned / custom','مملوك / خاص')}</dd></div><div><dt>${t('Your current preference','تفضيلك الحالي')}</dt><dd>${esc(platformName(s.decisions.platform))}</dd></div><div><dt>${t('Fulfilment route','مسار التنفيذ')}</dt><dd>${t('Saudi stock / warehouse partner','مخزون وشريك مستودع سعودي')}</dd></div><div><dt>${t('Merchant setup','إعداد التاجر')}</dt><dd>${t('Not confirmed','غير مؤكد')}</dd></div><div><dt>${t('Gates you marked verified','متطلبات أكدتَها محلياً')}</dt><dd>${countVerified()} / ${R.gates.length}</dd></div><div><dt>${t('Registration note','ملاحظة التسجيل')}</dt><dd>${t('Tax model settings are hypothetical, not the legal status.','إعدادات الضريبة افتراضية وليست الحالة القانونية.')}</dd></div></dl><h3>${t('Before more brands','قبل إضافة علامات')}</h3><ul class="audit-list"><li>${t('One correct paid, delivered and refunded order path.','مسار صحيح للطلب المدفوع والمسلّم والمسترد.')}</li><li>${t('Contribution after acquisition that survives actual costs.','مساهمة بعد الاستحواذ تصمد أمام التكلفة الفعلية.')}</li><li>${t('A distinct reason for a second brand to exist.','سبب مستقل لوجود العلامة الثانية.')}</li></ul></section></div><section>${sectionHead(t('Risks worth owning','مخاطر تستحق إدارة واضحة'),t('These are proposed operating risks, not measured incident probabilities.','مخاطر تشغيلية مقترحة وليست احتمالات حوادث مقاسة.'))}<div class="risk-list">${R.risks.map(r=>`<article class="risk-item risk-${r.severity}"><div><span class="pill ${r.severity==='high'?'pill-pending':'pill-assumption'}">${r.severity==='high'?t('High impact','أثر مرتفع'):t('Medium impact','أثر متوسط')}</span><h3>${esc(b(r.title))}</h3><p>${esc(b(r.impact))}</p></div><div><strong>${t('Control','الإجراء')}</strong><p>${esc(b(r.action))}</p><span class="fine">${esc(b(r.owner))}</span></div></article>`).join('')}</div></section>`;
  }

  function evidence() {
    return `${head(t('Follow the evidence.','اتبع الدليل.'),t('The original research, primary-source ledger and explicit limits behind the recommendation. Snapshot: 27 October 2026.','البحث الأصلي وسجل المصادر وحدود الأدلة وراء التوصية. لقطة بتاريخ 27 أكتوبر 2026.'),`<a class="button button-secondary" href="data/research-pack.zip" download>${icon('download')}${t('Research pack','حزمة البحث')}</a>`)}<div class="tabs" role="group" aria-label="${t('Evidence view','عرض الأدلة')}">${[['sources',t('Source library','مكتبة المصادر')],['memo',t('Full decision memo','مذكرة القرار الكاملة')],['limits',t('What is / is not proved','ما ثبت وما لم يثبت')]].map(([id,label])=>`<button class="tab ${s.evidenceTab===id?'is-active':''}" data-action="evidence-tab" data-tab="${id}" aria-pressed="${s.evidenceTab===id}">${label}</button>`).join('')}</div>${s.evidenceTab==='memo'?`<div class="panel"><p class="fine">${t('Initial fast-launch memo in English. Build paths expands it with managed, hybrid and owned delivery plans; Salla is an option, not a requirement. Tools are bilingual.','مذكرة الإطلاق السريع الأولى بالإنجليزية. توسّعها مسارات البناء بخطط مُدارة وهجينة ومملوكة؛ سلة خيار وليست متطلباً. الأدوات باللغتين.')}</p><div id="memo-body" class="memo-content" dir="ltr" lang="en"><p role="status">${t('Loading memo…','جارٍ تحميل المذكرة…')}</p></div></div>`:s.evidenceTab==='limits'?`<div class="panel panel-accent"><h2>${t('A useful recommendation with bounded confidence.','توصية مفيدة بحدود ثقة واضحة.')}</h2><p>${t('Source inspection and local configuration checks are complete. Production merchant validation and business results remain ahead.','اكتمل فحص المصادر واختبار الإعدادات محلياً. تحقق متجر التاجر والنتائج التجارية ما زالا أمامنا.')}</p></div><div class="grid-2"><section class="panel"><h2>${t('Completed','ما اكتمل')}</h2><ul class="audit-list"><li>${t('Current source audit: 23 variants, all commercial records pending.','تدقيق المصدر: 23 متغيراً، وبياناتها التجارية معلقة.')}</li><li>${t('Primary-source platform, market and regulatory investigation.','بحث المصادر الأصلية للمنصات والسوق والمتطلبات النظامية.')}</li><li>${t('Two configuration packages; 19 local checks passed.','حزمتا إعداد، و19 فحصاً محلياً ناجحاً.')}</li><li>${t('A cost model with explicit assumptions and calculations.','نموذج تكلفة بافتراضات ومعادلات صريحة.')}</li></ul></section><section class="panel"><h2>${t('Not yet proved','ما لم يثبت بعد')}</h2><ul class="audit-list">${R.currentLimitations.map(v=>`<li>${esc(b(v))}</li>`).join('')}</ul></section></div>`:`<div class="panel evidence-controls"><label class="field"><span class="field-label">${t('Search titles, claims or domains','ابحث في العناوين أو الادعاءات أو النطاقات')}</span><input type="search" class="number-input text-input" id="source-search" value="${esc(s.sourceQuery)}" placeholder="${t('Try payments, SFDA, theme, VAT…','جرّب: الدفع، SFDA، الثيم، VAT…')}"></label><label class="field"><span class="field-label">${t('Research area','مجال البحث')}</span><select class="select-input" id="source-area">${[['all',t('All sources','جميع المصادر')],['salla',t('Salla','سلة')],['zid',t('Zid','زد')],['shopify','Shopify'],['medusa','Medusa'],['saudi',t('Saudi / market / regulation','السعودية والسوق والأنظمة')],['technical',t('Technical evidence','أدلة تقنية')]].map(([id,label])=>`<option value="${id}" ${s.sourceArea===id?'selected':''}>${label}</option>`).join('')}</select></label></div><p class="fine" id="source-count" role="status"></p><div id="source-results" class="source-list"><p class="loading-state" role="status">${t('Loading sources…','جارٍ تحميل المصادر…')}</p></div>`}`;
  }

  function updateEconomics() {
    if(s.route!=='economics')return;
    const p=portfolioCosts(s.portfolio), technical=buildPlan(s.build), u=unitEconomics(s.unit,technical.monthlyRun);
    const put=(id,value)=>{const el=document.getElementById(id);if(el)el.textContent=value;};
    put('unit-profit',money(u.contributionAfterCAC,2));
    put('unit-before',money(u.contributionBeforeCAC,2));put('unit-max-cac',money(u.maxCAC,2));
    put('unit-verdict',u.contributionAfterCAC>0?t('Per delivered order, before fixed overhead.','لكل طلب مسلّم، قبل المصاريف الثابتة.'):t('This order loses money before fixed overhead. Change the assumptions or the offer.','هذا الطلب خاسر قبل المصاريف الثابتة. راجع الافتراضات أو العرض.'));
    document.getElementById('unit-profit')?.classList.toggle('is-loss',u.contributionAfterCAC<0);
    const rows=[[t('Net revenue','صافي الإيراد'),u.netRevenue,'revenue'],[t('Goods cost','تكلفة المنتجات'),-s.unit.cogs,'cost'],[t('Payment + platform','الدفع والمنصة'),-(u.pspCost+u.platformFee),'cost'],[t('Carrier','الناقل'),-s.unit.carrierCost,'cost'],[t('Handling + packaging','التجهيز والتغليف'),-(s.unit.pickPack+s.unit.packaging),'cost'],[t('Return / spoilage reserve','مخصص الإرجاع والتلف'),-s.unit.reserve,'cost'],[t('Before acquisition','قبل الاستحواذ'),u.contributionBeforeCAC,'subtotal'],[t('Acquisition','الاستحواذ'),-s.unit.cac,'cost'],[t('After acquisition','بعد الاستحواذ'),u.contributionAfterCAC,'total']];
    const max=Math.max(1,...rows.map(v=>Math.abs(v[1])));
    const wf=document.getElementById('unit-waterfall');if(wf)wf.innerHTML=rows.map(([label,value,kind])=>`<div class="waterfall-row ${kind}"><span>${label}</span><div class="waterfall-track"><span class="waterfall-fill ${kind==='cost'?'is-cost':value<0?'is-negative':''}" style="transform:scaleX(${Math.abs(value)/max})"></span></div><strong>${money(value,2)}</strong></div>`).join('');
    put('unit-formula',`${money(u.netRevenue,2)} − ${money(u.variableCost,2)} − ${money(s.unit.cac,2)} = ${money(u.contributionAfterCAC,2)}`);
    const sens=document.getElementById('cac-sensitivity');if(sens){const values=[0,15,30,45,60,75];const mx=Math.max(1,...values.map(v=>Math.abs(u.contributionBeforeCAC-v)));sens.innerHTML=values.map(v=>bar(`${t('CAC','استحواذ')} ${num(v)}`,u.contributionBeforeCAC-v,mx,u.contributionBeforeCAC-v<0?'negative':'' )).join('');}
    put('unit-fixed-context',technical.monthlyRun===0&&u.contributionAfterCAC>0?t('The modelled fixed-cost allowance is zero.','مخصص التكاليف الثابتة في النموذج صفر.'):u.breakEvenOrders==null?t('No positive per-order contribution to cover fixed costs in this scenario.','لا توجد مساهمة موجبة للطلب لتغطية التكاليف الثابتة في هذا السيناريو.'):`${t('Selected build plan / technical fixed allowance:','خطة البناء المختارة / المخصص التقني الثابت:')} ${money(technical.monthlyRun)} / ${t('month','شهر')} → ${num(Math.ceil(u.breakEvenOrders))} ${t('delivered orders/month to cover technical costs only. Retail overhead and unpriced fees remain additional.','طلباً مسلّماً شهرياً لتغطية التقنية فقط. يضاف التشغيل التجاري والرسوم غير المسعّرة.')}`);
    put('portfolio-year',money(p.firstYear));put('portfolio-setup',money(p.setup));put('portfolio-operating',money(p.annualOperating));
    const breakdown=document.getElementById('portfolio-breakdown');if(breakdown){const vals=[[t('Software + domains + apps','البرمجيات والنطاقات والتطبيقات'),p.software],[t('Shared technical care','متابعة تقنية مشتركة'),p.sharedCare],[t('Additional store technical care','متابعة تقنية لكل متجر'),p.storeCare],[t('Control / exports','الرقابة والتصدير'),p.operationsCare]];breakdown.innerHTML=vals.map(([a,v])=>bar(a,v,p.annualOperating)).join('');}
    const scaling=document.getElementById('portfolio-scaling');if(scaling){const ns=[...new Set([1,3,5,10,s.portfolio.stores])].sort((a,b)=>a-b);const vals=ns.map(n=>[n,portfolioCosts({...s.portfolio,stores:n}).annualOperating]);const mx=Math.max(...vals.map(v=>v[1]),1);scaling.innerHTML=vals.map(([n,v])=>bar(`${n} ${t('store(s)','متجر')}`,v,mx,n===s.portfolio.stores?'selected':'')).join('');}
    put('portfolio-hours',`${t('Launch labour:','جهد الإطلاق:')} ${num(p.engineeringHours)} ${t('engineering hours;','ساعة هندسة؛')} ${num(p.aggregateHours)} ${t('aggregate hours. External waiting and new brand creation are separate.','ساعة إجمالية. الانتظار الخارجي وتصميم العلامة الجديدة منفصلان.')}`);
  }

  function updateStack() {
    const ranking=document.getElementById('platform-ranking');if(!ranking)return;
    const total=Object.values(s.weights).reduce((a,v)=>a+v,0), scored=scorePlatforms(s.weights), ranked=[...scored.filter(p=>!Object.values(s.platformGates[p.id]||{}).includes('fail')),...scored.filter(p=>Object.values(s.platformGates[p.id]||{}).includes('fail'))];
    const label=document.getElementById('weight-total');if(label)label.textContent=total?`${t('Relative weights total:','مجموع الأوزان النسبية:')} ${num(total)}. ${t('Scores are normalised automatically.','تُطبّع الدرجات تلقائياً.')}`:t('All weights are zero. Set at least one priority to compare.','جميع الأوزان صفر. حدّد أولوية واحدة على الأقل للمقارنة.');
    ranking.innerHTML=ranked.map((p,i)=>{const failed=Object.values(s.platformGates[p.id]||{}).includes('fail');return `<button class="score-row ${p.id===s.stackInspect?'is-selected':''} ${failed?'is-excluded':''}" data-action="platform-detail" data-platform="${p.id}" aria-pressed="${p.id===s.stackInspect}"><span class="score-number">${failed?'—':String(i+1).padStart(2,'0')}</span><span class="score-name">${esc(platformName(p.id))}<small>${failed?t('Excluded by your trial mark','مستبعد بتأكيدك لفشل الاختبار'):t('Merchant proof pending','تجربة التاجر معلقة')}</small></span><span class="score-track"><span class="score-fill" style="transform:scaleX(${p.score/10})"></span></span><strong>${total&&!failed?num(p.score,1):'—'}</strong></button>`;}).join('');
  }

  function updateFactory() {
    const preview=document.getElementById('factory-preview');if(!preview)return;
    const sada=s.factory.brand==='sada', name=s.factory.name||(sada?'SADA':'NURIMI'), color=s.factory.accent||(sada?'#125c48':'#b82b55'), layout=s.factory.layout||(sada?'compact':'editorial');
    preview.style.setProperty('--preview-accent',color);preview.dataset.layout=layout;
    preview.innerHTML=`<div class="brand-preview-header"><strong>${esc(name)}<span>.</span></strong><span>${sada?t('INTERNAL BRAND TEST','اختبار علامة داخلي'):t('THE FIRST STORE','المتجر الأول')}</span></div><div class="preview-hero"><span>${sada?t('BODY CARE / EVERYDAY','عناية بالجسم / كل يوم'):t('SKIN FIRST','بشرتك أهم')}</span><h2>${sada?t('Daily care.<br>Less guesswork.','عناية يومية.<br>واختيار أوضح.'):t('Your skin.<br>Your choice.','بشرتك.<br>واختيارك.')}</h2><p>${sada?t('A compact, value-led assortment.','تشكيلة مختصرة تركز على القيمة.'):t('A thoughtful edit from four makers.','اختيارات مدروسة من أربع علامات.')}</p></div><div class="brand-preview-grid">${(sada?[['p022','Mixa','Ceramide Protect'],['p023','Mixa','Cica Réparation']]:[['p008','Anua','Heartleaf 77'],['p004','Arencia','Vitamin C']]).map(([img,maker,label])=>`<article class="product-mini"><img src="assets/${img}.webp" width="1024" height="1024" alt="${esc(`${maker} ${label}`)}" loading="lazy"><span>${esc(maker)}</span><strong>${esc(label)}</strong><small>${t('Commercial facts pending','البيانات التجارية معلقة')}</small></article>`).join('')}</div><div class="preview-footer">${t('Configuration preview · not a merchant deployment','معاينة إعدادات · ليست متجراً منشوراً')}</div>`;
    const a=allocation(10,s.allocation);const out=document.getElementById('allocation-primary');if(out)out.textContent=num(a.primary);const av=document.getElementById('allocation-visual');if(av)av.innerHTML=`<div class="allocation-units" aria-hidden="true">${Array.from({length:10},(_,i)=>`<span class="${i<a.primary?'nurimi-unit':'sada-unit'}"></span>`).join('')}</div><div class="allocation-labels"><strong>NURIMI ${num(a.primary)}</strong><strong>SADA ${num(a.secondary)}</strong></div><p>${t('Total offered:','الإجمالي المعروض:')} ${num(a.total)} / ${num(a.total)} ${t('physical units','وحدات فعلية')}</p>`;
  }

  return { render:route=>({overview,market,stack,economics,launch,factory,decisions,evidence}[route]||overview)(),updateEconomics,updateStack,updateFactory,platformDetail,statusLabel,gateCard,head };
}
